#!/usr/bin/env bash
# apply_worker_pr_pe.sh — Ftt-Otc-v6 PR: PENDING_ENTRY fill-correctness fix + v6.10.2
# Run from anywhere:  bash apply_worker_pr_pe.sh
# PR-first: verify guards -> git apply -> verify -> run tests -> branch -> commit -> push BRANCH (never main)
set -u

PATCH_B64=""
PATCH_SHA="24a2642c9b952b7501f2b87abc9376bb30e16136ee76b6a7df7060d870e92875"

fail() { echo "✗ $*" >&2; exit 1; }

command -v git >/dev/null || fail "git not installed"
command -v node >/dev/null || fail "node not installed"
cd ~/Ftt-Otc-v6 || fail "~/Ftt-Otc-v6 not found"

echo "── repo state check ──"
git fetch --quiet origin 2>/dev/null
BR=$(git rev-parse --abbrev-ref HEAD)
[ "$BR" = "main" ] || fail "not on main (on '$BR') — switch: git checkout main"
DIRTY=$(git status --porcelain)
[ -z "$DIRTY" ] || fail "working tree not clean:\n$DIRTY\n  commit or stash first"

echo "── guards: expected OLD content present? ──"
grep -q 'const winLoss = classifyOutcome' src/history/stats.js || fail "stats.js: expected 'const winLoss' not found — repo differs; aborting"
grep -q "version: '6.10.1'" src/handlers/health.js || fail "health.js: expected version 6.10.1 not found — repo differs; aborting"
grep -q 'T43j' scripts/fix_tests.mjs || fail "fix_tests.mjs: T43j not found — repo differs; aborting"
echo "  ✓ old content confirmed"

echo "── decode + verify patch ──"
printf '%s' "$PATCH_B64" | base64 -d > $HOME/pe_v6102.patch
ACT=$(sha256sum $HOME/pe_v6102.patch | cut -d' ' -f1)
[ "$ACT" = "$PATCH_SHA" ] || fail "patch sha mismatch: got $ACT"
echo "  ✓ patch sha ok"

echo "── apply ──"
git apply --check $HOME/pe_v6102.patch || fail "git apply --check failed"
git apply $HOME/pe_v6102.patch || fail "git apply failed"
rm -f $HOME/pe_v6102.patch

echo "── verify new content ──"
grep -q "fillStatus === 'PENDING_ENTRY' && record.entryHit === false" src/history/stats.js || fail "fill fix not present"
grep -q "version: '6.10.2'" src/handlers/health.js || fail "version not 6.10.2"
grep -q 'T44a' scripts/fix_tests.mjs || fail "T44 test not present"
bash -n scripts/redeploy.sh || fail "redeploy.sh bash -n failed"
echo "  ✓ content verified"

echo "── tests (must be green) ──"
node --check src/history/stats.js || fail "stats.js syntax"
OUT=$(node scripts/fix_tests.mjs 2>&1 | tail -n 2)
echo "$OUT"
echo "$OUT" | grep -q "PASS: 311" || fail "fix_tests not 311/0"
echo "  ✓ fix_tests 311/0"

echo "── diff (review) ──"
git --no-pager diff --stat
git --no-pager diff -- src/history/stats.js | head -n 60

echo "── branch + commit + push (BRANCH ONLY) ──"
git checkout -b fix/pending-entry-fill-correctness
git add src/history/stats.js src/handlers/health.js src/index.js scripts/fix_tests.mjs scripts/redeploy.sh
git commit -m "fix(stats): PENDING_ENTRY unfilled -> TIE (no mechanical WIN) + v6.10.2" || fail "commit failed"
git push -u origin fix/pending-entry-fill-correctness || fail "push failed (check auth — no tokens in chat)"

echo ""
echo "═══ DONE — branch pushed ═══"
echo "PR title : fix(stats): PENDING_ENTRY unfilled trades must not count as mechanical WIN (v6.10.2)"
echo "PR body  : ~/Workplace-drive-/pr/PR_BODY_pe_fill_correctness.md"
echo "Open PR  : https://github.com/ferdausfs/Ftt-Otc-v6/compare/fix/pending-entry-fill-correctness"
echo "After merge: git checkout main && git pull"
